5ad3118e-de31-47ce-be2d-f2fe7ff77cff	Procurement Specification Draft for PVC Insulated Low-Voltage Electrical Cables	We need to procure 500 metres of PVC insulated low-voltage electrical cables for power distribution in a commercial building. The cables should have suitable conductor size, insulation, voltage rating and flame-retardant properties and should comply with applicable BIS standards.	other	routine	{"keywords": ["PVC insulated", "low-voltage", "electrical cables", "conductor size", "insulation", "voltage rating", "flame-retardant", "BIS standards"], "products": ["PVC insulated low-voltage electrical cables"], "applications": ["power distribution in a commercial building"], "intent_summary": "Procurement of 500 metres of PVC insulated low-voltage electrical cables with flame-retardant properties for commercial building power distribution, complying with applicable BIS standards."}	{"recommendations": [{"title": "PVC Insulated Cables for Working Voltages up to 1,100 V", "status": "CURRENT", "sources": [{"url": "https://www.services.bis.gov.in/php/BIS_2.0/bisconnect/knowyourstandards/indian_standards/isdetails", "page": null, "title": null, "section": null, "source_type": "Official Standard", "organization": "Bureau of Indian Standards", "retrieved_at": "2026-09-27T18:05:26.583040+05:30", "document_name": null}], "version": {"status": "CURRENT", "edition": "2010", "effective_date": null, "publication_date": null}, "evidence": [{"type": "PRODUCT_MATCH", "label": "Product Match", "source": null, "description": "Requirement product(s) 'PVC insulated low-voltage electrical cables' found in standard scope."}, {"type": "KEYWORD_MATCH", "label": "Keyword Match", "source": null, "description": "Requirement keyword(s) 'electrical cables, voltage rating, low-voltage, PVC insulated' match standard terms."}, {"type": "SCOPE_MATCH", "label": "Scope Match", "source": {"url": "https://www.services.bis.gov.in/php/BIS_2.0/bisconnect/knowyourstandards/indian_standards/isdetail